SET NOCOUNT ON;SET XACT_ABORT ON;INSERT lab.Evidence(Stage,UserPages,InternalPages,VersionStorePages)SELECT 'BASELINE',user_objects_alloc_page_count-user_objects_dealloc_page_count,internal_objects_alloc_page_count-internal_objects_dealloc_page_count,(SELECT SUM(version_store_reserved_page_count) FROM tempdb.sys.dm_db_file_space_usage) FROM tempdb.sys.dm_db_session_space_usage WHERE session_id=@@SPID;PRINT 'SQLPERF_SUMMARY|PASS|OK';
